Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
netfilter: nf_conncount: update last_gc only when GC has been
 performed

Currently last_gc is being updated everytime a new connection is
tracked, that means that it is updated even if a GC wasn't performed.
With a sufficiently high packet rate, it is possible to always bypass
the GC, causing the list to grow infinitely.

Update the last_gc value only when a GC has been actually performed.

Fixes: d265929930e2 ("netfilter: nf_conncount: reduce unnecessary GC")
Signed-off-by: Fernando Fernandez Mancera <fmancera@suse.de>
Signed-off-by: Florian Westphal <fw@strlen.de>

Here is the root cause:
The `last_gc` timestamp was updated on every new connection addition, even when no garbage collection occurred. Under high packet rates, this prevented the GC from ever being triggered because the time since the last update was always recent, allowing the connection list to grow without bound.

Here is the patch:

 static int __nf_conncount_add(struct net *net,
 			      const struct sk_buff *skb,
 			      u16 l3num,
 			      struct nf_conncount_list *list)
 {
 	const struct nf_conntrack_zone *zone = &nf_ct_zone_dflt;
 	const struct nf_conntrack_tuple_hash *found;
 	struct nf_conncount_tuple *conn, *conn_n;
 	struct nf_conntrack_tuple tuple;
 	struct nf_conn *ct = NULL;
 	struct nf_conn *found_ct;
 	unsigned int collect = 0;
 	bool refcounted = false;
 	int err = 0;

 	if (!get_ct_or_tuple_from_skb(net, skb, l3num, &ct, &tuple, &zone, &refcounted))
 		return -ENOENT;

 	if (ct && nf_ct_is_confirmed(ct)) {
 		err = -EEXIST;
 		goto out_put;
 	}

 	if ((u32)jiffies == list->last_gc)
 		goto add_new_node;

 	/* check the saved connections */
 	list_for_each_entry_safe(conn, conn_n, &list->head, node) {
 		if (collect > CONNCOUNT_GC_MAX_NODES)
 			break;

 		found = find_or_evict(net, list, conn);
 		if (IS_ERR(found)) {
 			/* Not found, but might be about to be confirmed */
 			if (PTR_ERR(found) == -EAGAIN) {
 				if (nf_ct_tuple_equal(&conn->tuple, &tuple) &&
 				    nf_ct_zone_id(&conn->zone, conn->zone.dir) ==
 				    nf_ct_zone_id(zone, zone->dir))
 					goto out_put; /* already exists */
 			} else {
 				collect++;
 			}
 			continue;
 		}

 		found_ct = nf_ct_tuplehash_to_ctrack(found);

 		if (nf_ct_tuple_equal(&conn->tuple, &tuple) &&
 		    nf_ct_zone_equal(found_ct, zone, zone->dir)) {
 			/*
 			 * We should not see tuples twice unless someone hooks
 			 * this into a table without "-p tcp --syn".
 			 *
 			 * Attempt to avoid a re-add in this case.
 			 */
 			nf_ct_put(found_ct);
 			goto out_put;
 		} else if (already_closed(found_ct)) {
 			/*
 			 * we do not care about connections which are
 			 * closed already -> ditch it
 			 */
 			nf_ct_put(found_ct);
 			conn_free(list, conn);
 			collect++;
 			continue;
 		}

 		nf_ct_put(found_ct);
 	}
+	list->last_gc = (u32)jiffies;

 add_new_node:
 	if (WARN_ON_ONCE(list->count > INT_MAX)) {
 		err = -EOVERFLOW;
 		goto out_put;
 	}

 	conn = kmem_cache_alloc(conncount_conn_cachep, GFP_ATOMIC);
 	if (conn == NULL) {
 		err = -ENOMEM;
 		goto out_put;
 	}

 	conn->tuple = tuple;
 	conn->zone = *zone;
 	conn->cpu = raw_smp_processor_id();
 	conn->jiffies32 = (u32)jiffies;
 	list_add_tail(&conn->node, &list->head);
 	list->count++;
-	list->last_gc = (u32)jiffies;

 out_put:
 	if (refcounted)
 		nf_ct_put(ct);
 	return err;
 }



